  app.get("/api/compliance/2026-status", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = await resolveUserId(req);
      const currentVersion = "2026-02-16-v1";

      const nppAck = await db.select().from(nppAcknowledgments)
        .where(sql`${nppAcknowledgments.userId} = ${userId} AND ${nppAcknowledgments.nppVersion} = ${currentVersion}`)
        .limit(1);

      const pendingRequests = await db.select().from(dataAccessRequests)
        .where(sql`${dataAccessRequests.userId} = ${userId} AND ${dataAccessRequests.status} != 'completed' AND ${dataAccessRequests.status} != 'denied'`);

      const overdueRequests = pendingRequests.filter(r => new Date(r.dueDate) < new Date());

      res.json({
        hipaa2026: {
          nppUpdated: true,
          nppVersion: currentVersion,
          nppEffectiveDate: "2026-02-16",
          patientAcknowledged: nppAck.length > 0,
          acknowledgedAt: nppAck.length > 0 ? nppAck[0].acknowledgedAt : null,
          sudProtectionsIncluded: true,
          reproductiveHealthProtectionsIncluded: true,
          compliant: true,
        },
        informationBlocking: {
          regulation: "ONC HTI-1",
          maxResponseDays: 15,
          pendingRequests: pendingRequests.length,
          overdueRequests: overdueRequests.length,
          compliant: overdueRequests.length === 0,
        },
        overallCompliant: nppAck.length > 0 && overdueRequests.length === 0,
      });
    } catch (error) {
      console.error("2026 compliance status error:", error);
      res.status(500).json({ error: "Failed to check 2026 compliance status" });
    }
  });

