  // Start sync job

  app.post("/api/fhir-connections/:id/sync", requireAuth, async (req: Request, res: Response) => {
    try {
      const sourceId = (req.params as any).id as string;
      const userId = getUserId(req);
      const { direction = "import", resourceTypes } = req.body as any;
      
      const source = await storage.getDataSource(sourceId);
      if (!source || source.userId !== userId) {
        return res.status(404).json({ error: "Connection not found" });
      }
      
      // Check for existing active sync
      const activeJobs = await storage.getActiveSyncJobs(userId);
      const existingSync = activeJobs.find((j: any) => j.sourceId === sourceId);
      if (existingSync) {
        return res.status(409).json({ error: "A sync is already in progress for this connection", jobId: existingSync.id });
      }
      
      // Create sync job
      const syncJob = await storage.createFhirSyncJob({
        userId,
        sourceId,
        direction,
        status: "pending",
        phase: "authentication",
        resourceTypes: resourceTypes || null,
        startedAt: new Date(),
      });
      
      auditLog(req, "start_fhir_sync", "fhir_sync_job", syncJob.id, { direction, resourceTypes });
      
      // Start sync in background
      processSyncJob(syncJob.id, source, direction).catch(err => {
        console.error("Sync job error:", err);
        storage.updateFhirSyncJob(syncJob.id, { 
          status: "failed",
          errors: [{ message: err.message, timestamp: new Date().toISOString() }],
          completedAt: new Date(),
        });
      });
      
      res.status(202).json(syncJob);
    } catch (error) {
      console.error("Start sync error:", error);
      res.status(500).json({ error: "Failed to start sync" });
    }
  });

