  app.patch("/api/records/:id", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const oldRecord = await storage.getHealthRecord((req.params as any).id as string);
      if (!oldRecord) {
        return res.status(404).json({ error: "Record not found" });
      }
      if (oldRecord.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const record = await storage.updateHealthRecord((req.params as any).id as string, req.body);
      if (!record) {
        return res.status(404).json({ error: "Record not found" });
      }

      if (record.type === "condition" && oldRecord) {
        const records = await storage.getHealthRecords(userId);
        clinicalAutomationEngine.processTrigger(
          {
            id: `auto_update_${Date.now()}`,
            type: "diagnosis_updated",
            patientId: userId,
            recordId: record.id,
            data: { title: record.title, summary: record.summary, previousTitle: oldRecord.title, previousSummary: oldRecord.summary, ...req.body },
            timestamp: new Date(),
          },
          records
        ).catch(err => console.error("[AutomationEngine] Background trigger error:", err));
      }

      if (req.body.status && req.body.status !== oldRecord?.summary) {
        const statusVal = (req.body.status || "").toLowerCase();
        if (statusVal === "discharged" || statusVal === "transferred" || statusVal === "referred") {
          const records = await storage.getHealthRecords(userId);
          clinicalAutomationEngine.processTrigger(
            {
              id: `auto_status_${Date.now()}`,
              type: "status_changed",
              patientId: userId,
              recordId: record.id,
              data: { newStatus: statusVal, title: record.title, ...req.body },
              timestamp: new Date(),
            },
            records
          ).catch(err => console.error("[AutomationEngine] Background trigger error:", err));
        }
      }

      res.json(record);
    } catch (error) {
      res.status(500).json({ error: "Failed to update record" });
    }
  });


