  app.post("/api/records/:id/attachments", requireAuth, uploadMiddleware.single("file"), async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const record = await storage.getHealthRecord((req.params as any).id);
      if (!record) {
        return res.status(404).json({ error: "Record not found" });
      }
      if (record.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      const file = req.file;
      if (!file) {
        return res.status(400).json({ error: "No file provided" });
      }

      const allowedTypes = ["application/pdf", "image/jpeg", "image/png", "image/heic", "image/webp"];
      if (!allowedTypes.includes(file.mimetype)) {
        const fsPromises = await import("fs/promises");
        await fsPromises.unlink(file.path).catch(() => {});
        return res.status(400).json({ error: "File type not allowed. Supported: PDF, JPEG, PNG, HEIC, WebP" });
      }

      const maxSize = 10 * 1024 * 1024;
      if (file.size > maxSize) {
        const fsPromises = await import("fs/promises");
        await fsPromises.unlink(file.path).catch(() => {});
        return res.status(400).json({ error: "File size exceeds 10MB limit" });
      }

      const attachment = await storage.createRecordAttachment({
        recordId: (req.params as any).id,
        userId,
        fileName: file.originalname.replace(/[^a-zA-Z0-9._-]/g, "_").substring(0, 255),
        fileType: file.mimetype,
        fileSize: file.size,
        filePath: file.path,
      });

      auditLog(req, "upload_attachment", "record_attachment", attachment.id);
      res.status(201).json(attachment);
    } catch (error) {
      res.status(500).json({ error: "Failed to upload attachment" });
    }
  });


