      const target = attachments.find(a => a.id === (req.params as any).attachmentId);
      if (!target) {
        return res.status(404).json({ error: "Attachment not found" });
      }
      if (target.userId !== userId) {
        auditLog(req, "unauthorized_delete_attempt", "record_attachment", (req.params as any).attachmentId);
        return res.status(403).json({ error: "Access denied" });
      }
      const resolvedPath = path.resolve(target.filePath);
      const resolvedUploadsDir = path.resolve(uploadsDir);
      if (resolvedPath.startsWith(resolvedUploadsDir)) {
        fs.unlink(resolvedPath, () => {});
      }
      await storage.deleteRecordAttachment((req.params as any).attachmentId);
      auditLog(req, "delete_attachment", "record_attachment", (req.params as any).attachmentId);
