  app.get("/api/attachments/:id/file", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const [attachment] = await db.select().from(recordAttachments).where(and(eq(recordAttachments.id, (req.params as any).id), eq(recordAttachments.userId, userId)));
      if (!attachment) {
        return res.status(404).json({ error: "Attachment not found" });
      }

      const resolvedPath = path.resolve(attachment.filePath);
      const resolvedUploadsDir = path.resolve(uploadsDir);
      if (!resolvedPath.startsWith(resolvedUploadsDir)) {
        auditLog(req, "path_traversal_attempt", "record_attachment", (req.params as any).id);
        return res.status(403).json({ error: "Access denied" });
      }

      if (!fs.existsSync(resolvedPath)) {
        return res.status(404).json({ error: "File not found" });
      }

      const sanitizedName = attachment.fileName.replace(/[^a-zA-Z0-9._-]/g, "_");
      res.setHeader("Content-Type", attachment.fileType);
      res.setHeader("Content-Disposition", `inline; filename="${sanitizedName}"`);
      res.setHeader("X-Content-Type-Options", "nosniff");
      res.setHeader("Content-Security-Policy", "default-src 'none'; style-src 'unsafe-inline'");
      res.setHeader("Cache-Control", "private, no-cache, no-store, must-revalidate");
      fs.createReadStream(resolvedPath).pipe(res);
    } catch (error) {
      res.status(500).json({ error: "Failed to serve attachment" });
    }
  });


