  app.get("/api/records/duplicates/scan", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const allRecords = await storage.getHealthRecords(userId);

      interface DuplicateGroup {
        key: string;
        records: typeof allRecords;
        reason: string;
      }

      const duplicateGroups: DuplicateGroup[] = [];
      const seen = new Map<string, typeof allRecords>();

      for (const record of allRecords) {
        const dateStr = record.date ? new Date(record.date).toISOString().split("T")[0] : "no-date";
        const normalizedTitle = (record.title || "").toLowerCase().trim().replace(/\s+/g, " ");
        const normalizedType = (record.type || "").toLowerCase().trim();

        const exactKey = `${normalizedType}|${dateStr}|${normalizedTitle}`;
        if (!seen.has(exactKey)) {
          seen.set(exactKey, []);
        }
        seen.get(exactKey)!.push(record);

        if (record.fhirResourceId && record.fhirResourceType) {
          const fhirKey = `fhir|${record.fhirResourceType}|${record.fhirResourceId}`;
          if (!seen.has(fhirKey)) {
            seen.set(fhirKey, []);
          }
          seen.get(fhirKey)!.push(record);
        }
      }

      const processedIds = new Set<string>();

      for (const [key, records] of seen.entries()) {
        if (records.length > 1) {
          const uniqueRecords = records.filter(r => !processedIds.has(r.id));
          if (uniqueRecords.length > 1) {
            const uniqueById = new Map(uniqueRecords.map(r => [r.id, r]));
            const dedupedRecords = Array.from(uniqueById.values());
            if (dedupedRecords.length > 1) {
              const reason = key.startsWith("fhir|")
                ? "Same FHIR resource ID and type"
                : "Same record type, date, and title";
              duplicateGroups.push({ key, records: dedupedRecords, reason });
              dedupedRecords.forEach(r => processedIds.add(r.id));
            }
          }
        }
      }

      res.json({
        totalRecords: allRecords.length,
        duplicateGroups: duplicateGroups.length,
        duplicateRecords: duplicateGroups.reduce((sum, g) => sum + g.records.length - 1, 0),
        groups: duplicateGroups.map(g => ({
          reason: g.reason,
          count: g.records.length,
          keepRecord: g.records[0],
          duplicates: g.records.slice(1),
        })),
      });
    } catch (error) {
      console.error("Scan duplicates error:", error);
      res.status(500).json({ error: "Failed to scan for duplicate records" });
    }
  });


  app.post("/api/records/duplicates/clean", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { groupKeys, autoClean } = req.body as any;
      const allRecords = await storage.getHealthRecords(userId);

      const seen = new Map<string, typeof allRecords>();

      for (const record of allRecords) {
        const dateStr = record.date ? new Date(record.date).toISOString().split("T")[0] : "no-date";
        const normalizedTitle = (record.title || "").toLowerCase().trim().replace(/\s+/g, " ");
        const normalizedType = (record.type || "").toLowerCase().trim();
        const exactKey = `${normalizedType}|${dateStr}|${normalizedTitle}`;
        if (!seen.has(exactKey)) seen.set(exactKey, []);
        seen.get(exactKey)!.push(record);

        if (record.fhirResourceId && record.fhirResourceType) {
          const fhirKey = `fhir|${record.fhirResourceType}|${record.fhirResourceId}`;
          if (!seen.has(fhirKey)) seen.set(fhirKey, []);
          seen.get(fhirKey)!.push(record);
        }
      }

      let removed = 0;
      const removedIds: string[] = [];

      const groupsToClean = autoClean
        ? Array.from(seen.entries()).filter(([_, records]) => records.length > 1)
        : (groupKeys || []).map((k: string) => [k, seen.get(k) || []] as const).filter(([_, r]: [string, typeof allRecords]) => r.length > 1);

      for (const [_, records] of groupsToClean) {
        const sorted = [...records].sort((a, b) => {
          const aUpdated = a.updatedAt ? new Date(a.updatedAt).getTime() : 0;
          const bUpdated = b.updatedAt ? new Date(b.updatedAt).getTime() : 0;
          if (aUpdated !== bUpdated) return bUpdated - aUpdated;
          const aHasDetails = a.details && Object.keys(a.details as object).length > 0;
          const bHasDetails = b.details && Object.keys(b.details as object).length > 0;
          if (aHasDetails && !bHasDetails) return -1;
          if (!aHasDetails && bHasDetails) return 1;
          return 0;
        });

        for (let i = 1; i < sorted.length; i++) {
          if (!removedIds.includes(sorted[i].id)) {
            await storage.deleteHealthRecord(sorted[i].id);
            removedIds.push(sorted[i].id);
            removed++;
          }
        }
      }

      auditLog(req, "clean_duplicate_records", "health_record", undefined, { removed, removedIds });

      res.json({
        success: true,
        removed,
        removedIds,
        message: `Removed ${removed} duplicate health record(s). The most complete version of each record was kept.`,
      });
    } catch (error) {
      console.error("Clean duplicates error:", error);
      res.status(500).json({ error: "Failed to clean duplicate records" });
    }
  });


