  app.post("/api/sources/:id/sync", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const source = await storage.getDataSource((req.params as any).id as string);
      if (!source) {
        return res.status(404).json({ error: "Source not found" });
      }
      if (source.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }

      auditLog(req, "sync_source", "data_source", source.id);

      if (source.accessToken && source.patientId && source.clientId) {
        const count = await syncEpicRecords(
          userId,
          source.id,
          source.clientId,
          source.patientId,
          source.accessToken
        );
        res.json({ success: true, message: "Sync completed", recordsImported: count });
      } else {
        await storage.updateDataSource(source.id, { lastSyncAt: new Date() });
        res.json({ success: true, message: "Sync initiated" });
      }
    } catch (error) {
      res.status(500).json({ error: "Failed to sync source" });
    }
  });


