  app.post("/api/share-links", requireAuth, requireFeature("provider_sharing"), async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const { expiresInHours = 24, passcode, recordIds, categories, dateRangeStart, dateRangeEnd } = req.body as any;

      const expiresAt = new Date(Date.now() + expiresInHours * 60 * 60 * 1000);

      const link = await storage.createShareLink({
        userId,
        token: "",
        passcode: passcode || null,
        expiresAt,
        isRevoked: false,
        recordIds: recordIds || null,
        categories: categories || null,
        dateRangeStart: dateRangeStart ? new Date(dateRangeStart) : null,
        dateRangeEnd: dateRangeEnd ? new Date(dateRangeEnd) : null,
      });

      auditLog(req, "create_share_link", "share_link", link.id);
      
      await storage.createShareLinkAccessLog({
        shareLinkId: link.id,
        action: "created",
        accessorIp: req.ip || null,
        accessorUserAgent: getHeader(req, "user-agent") || null,
        metadata: { expiresInHours, hasPasscode: !!passcode },
      });

      const baseUrl = process.env.REPLIT_DEV_DOMAIN
        ? `https://${process.env.REPLIT_DEV_DOMAIN}`
        : "http://localhost:5000";

      res.status(201).json({
        ...link,
        shareUrl: `${baseUrl}/share/${link.token}`,
      });
    } catch (error) {
      console.error("Create share link error:", error);
      res.status(500).json({ error: "Failed to create share link" });
    }
  });


  app.post("/api/share-links/:id/revoke", requireAuth, async (req: Request, res: Response) => {
    try {
      const userId = getUserId(req);
      const id = (req.params as any).id as string;
      const link = await storage.getShareLinkById(id);
      if (!link) {
        return res.status(404).json({ error: "Share link not found" });
      }
      if (link.userId !== userId) {
        return res.status(403).json({ error: "Access denied" });
      }
      auditLog(req, "revoke_share_link", "share_link", id);
      
      await storage.createShareLinkAccessLog({
        shareLinkId: id,
        action: "revoked",
        accessorIp: req.ip || null,
        accessorUserAgent: getHeader(req, "user-agent") || null,
        metadata: { revokedBy: userId },
      });
      
      await storage.revokeShareLink(id);
      res.json({ success: true });
    } catch (error) {
      res.status(500).json({ error: "Failed to revoke share link" });
    }
  });
